SET site_name = #{siteName}, site_title = #{siteTitle}, tagline = #{tagline},
    site_description = #{siteDescription}, home_intro = #{homeIntro},
    footer_text = #{footerText}, logo_media_asset_id = #{logoMediaAssetId},
    favicon_media_asset_id = #{faviconMediaAssetId}, updated_at = #{updatedAt}
WHERE id = #{id}
